using Azure.AI.Inference;
using Azure.Identity;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using OpenTelemetry;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

namespace MyApp.Eval;

/// <summary>
/// Shared setup for telemetry, quality evaluators, and compare mode.
/// </summary>
internal static class EvalSetup
{
    private static readonly string Endpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
        ?? "https://your-resource.openai.azure.com";

    private static readonly string ModelDeployment =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini";

    // ─── Telemetry ────────────────────────────────────────────────────────────
    public static TracerProvider BuildTelemetry()
    {
        return Sdk.CreateTracerProviderBuilder()
            .SetResourceBuilder(ResourceBuilder.CreateDefault().AddService("MyApp.Eval"))
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("MyApp.Eval")
            .AddOtlpExporter()       // sends to OTEL_EXPORTER_OTLP_ENDPOINT
            .AddConsoleExporter()    // local debugging
            .Build()!;
    }

    // ─── Chat client under evaluation ─────────────────────────────────────────
    public static IChatClient CreateChatClient()
    {
        return new ChatClientBuilder(
                new ChatCompletionsClient(new Uri(Endpoint), new DefaultAzureCredential())
                    .AsChatClient(ModelDeployment))
            .UseOpenTelemetry(sourceName: "MyApp.Eval")
            .Build();
    }

    // ─── Quality evaluators ───────────────────────────────────────────────────
    public static IEvaluator[] QualityEvaluators(IChatClient judge)
    {
        return
        [
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        ];
    }

    // ─── Reporting (compare mode) ─────────────────────────────────────────────
    public static ReportingConfiguration CreateReportingConfig(string runLabel)
    {
        var storageDir = Path.Combine(
            Path.GetDirectoryName(typeof(EvalSetup).Assembly.Location)!,
            "eval-results");

        return new ReportingConfiguration(
            storageRootPath: storageDir,
            executionName: runLabel,
            chatConfiguration: null);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry.Trace;
using System.Text.Json;

namespace MyApp.Eval;

[TestClass]
public sealed class QualityTests
{
    private static TracerProvider s_telemetry = null!;
    private static IChatClient s_chatClient = null!;
    private static IChatClient s_judge = null!;

    [ClassInitialize]
    public static void Init(TestContext _)
    {
        s_telemetry = EvalSetup.BuildTelemetry();
        s_chatClient = EvalSetup.CreateChatClient();
        s_judge = EvalSetup.CreateChatClient(); // judge model
    }

    [ClassCleanup]
    public static void Cleanup()
    {
        s_telemetry?.Dispose();
        (s_chatClient as IDisposable)?.Dispose();
        (s_judge as IDisposable)?.Dispose();
    }

    [TestMethod]
    [DynamicData(nameof(LoadScenarios), DynamicDataSourceType.Method)]
    public async Task Quality_MeetsThreshold(string name, string userMessage, string context)
    {
        // Arrange
        var messages = new List<ChatMessage> { new(ChatRole.User, userMessage) };
        var evaluators = EvalSetup.QualityEvaluators(s_judge);

        // Act
        var response = await s_chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        // Evaluate
        var evalResults = new Dictionary<string, EvaluationResult>();
        foreach (var evaluator in evaluators)
        {
            var result = await evaluator.EvaluateAsync(messages, new EvaluatorContext
            {
                GroundTruthContext = context
            });
            foreach (var kvp in result)
                evalResults[kvp.Key] = kvp.Value;
        }

        // Assert all quality scores ≥ 3/5
        foreach (var (metric, result) in evalResults)
        {
            var score = result.NumericScore;
            Assert.IsTrue(
                score >= 3,
                $"[{name}] {metric} scored {score}/5 — below threshold.");
        }
    }

    private static IEnumerable<object[]> LoadScenarios()
    {
        var path = Path.Combine(
            Path.GetDirectoryName(typeof(QualityTests).Assembly.Location)!,
            "Scenarios", "quality.json");

        if (!File.Exists(path))
            yield break;

        var scenarios = JsonSerializer.Deserialize<List<QualityScenario>>(
            File.ReadAllText(path))!;

        foreach (var s in scenarios)
            yield return [s.Name, s.UserMessage, s.Context ?? ""];
    }
}

internal record QualityScenario(string Name, string UserMessage, string? Context);

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using System.Text.Json;

namespace MyApp.Eval;

/// <summary>
/// Compare mode: runs the same scenarios against two configurations and
/// writes results to the reporting store for side-by-side diff.
/// </summary>
[TestClass]
public sealed class CompareTests
{
    private static readonly string RunLabel =
        Environment.GetEnvironmentVariable("EVAL_RUN_LABEL") ?? $"run-{DateTime.UtcNow:yyyyMMdd-HHmmss}";

    [TestMethod]
    [DynamicData(nameof(LoadScenarios), DynamicDataSourceType.Method)]
    public async Task Compare_RecordResults(string name, string userMessage, string context)
    {
        var config = EvalSetup.CreateReportingConfig(RunLabel);

        using var chatClient = EvalSetup.CreateChatClient();
        var judge = EvalSetup.CreateChatClient();
        var evaluators = EvalSetup.QualityEvaluators(judge);

        var messages = new List<ChatMessage> { new(ChatRole.User, userMessage) };
        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var scores = new Dictionary<string, EvaluationResult>();
        foreach (var evaluator in evaluators)
        {
            var result = await evaluator.EvaluateAsync(messages, new EvaluatorContext
            {
                GroundTruthContext = context
            });
            foreach (var kvp in result)
                scores[kvp.Key] = kvp.Value;
        }

        // Persist for comparison across runs
        await config.WriteResultsAsync(name, scores);
    }

    private static IEnumerable<object[]> LoadScenarios()
    {
        var path = Path.Combine(
            Path.GetDirectoryName(typeof(CompareTests).Assembly.Location)!,
            "Scenarios", "quality.json");

        if (!File.Exists(path))
            yield break;

        var scenarios = JsonSerializer.Deserialize<List<QualityScenario>>(
            File.ReadAllText(path))!;

        foreach (var s in scenarios)
            yield return [s.Name, s.UserMessage, s.Context ?? ""];
    }
}

using Microsoft.Extensions.AI;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry.Trace;
using System.Diagnostics;

namespace MyApp.Eval;

/// <summary>
/// Telemetry mode: validates that AI interactions produce proper
/// OpenTelemetry spans with expected attributes.
/// </summary>
[TestClass]
public sealed class TelemetryTests
{
    private static readonly ActivitySource Source = new("MyApp.Eval");

    [TestMethod]
    public async Task Telemetry_EmitsSpanForChatCompletion()
    {
        var exportedSpans = new List<Activity>();

        using var tp = OpenTelemetry.Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("MyApp.Eval")
            .AddInMemoryExporter(exportedSpans)
            .Build()!;

        using var client = EvalSetup.CreateChatClient();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Say hello in one word.")
        };

        var response = await client.GetResponseAsync(messages);

        tp.ForceFlush();

        Assert.IsTrue(exportedSpans.Count > 0, "Expected at least one telemetry span.");

        var chatSpan = exportedSpans.FirstOrDefault(a =>
            a.DisplayName.Contains("chat", StringComparison.OrdinalIgnoreCase));

        Assert.IsNotNull(chatSpan, "Expected a 'chat' span from the AI client pipeline.");
    }

    [TestMethod]
    public async Task Telemetry_SpanContainsModelAttribute()
    {
        var exportedSpans = new List<Activity>();

        using var tp = OpenTelemetry.Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("MyApp.Eval")
            .AddInMemoryExporter(exportedSpans)
            .Build()!;

        using var client = EvalSetup.CreateChatClient();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is 2+2?")
        };

        await client.GetResponseAsync(messages);
        tp.ForceFlush();

        var chatSpan = exportedSpans.FirstOrDefault(a =>
            a.DisplayName.Contains("chat", StringComparison.OrdinalIgnoreCase));

        Assert.IsNotNull(chatSpan);

        var modelTag = chatSpan.Tags.FirstOrDefault(t =>
            t.Key.Contains("model", StringComparison.OrdinalIgnoreCase));

        Assert.IsNotNull(modelTag.Value, "Expected model attribute on the chat span.");
    }
}

