using Azure.AI.Inference;
using Azure.Identity;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using OpenTelemetry;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

namespace MyApp.Eval;

/// <summary>
/// Shared setup for telemetry, quality evaluators, and compare mode.
/// </summary>
internal static class EvalSetup
{
    private static readonly string Endpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
        ?? "https://your-resource.openai.azure.com";

    private static readonly string ModelDeployment =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini";

    // ─── Telemetry ────────────────────────────────────────────────────────────
    public static TracerProvider BuildTelemetry()
    {
        return Sdk.CreateTracerProviderBuilder()
            .SetResourceBuilder(ResourceBuilder.CreateDefault().AddService("MyApp.Eval"))
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("MyApp.Eval")
            .AddOtlpExporter()       // sends to OTEL_EXPORTER_OTLP_ENDPOINT
            .AddConsoleExporter()    // local debugging
            .Build()!;
    }

    // ─── Chat client under evaluation ─────────────────────────────────────────
    public static IChatClient CreateChatClient()
    {
        return new ChatClientBuilder(
                new ChatCompletionsClient(new Uri(Endpoint), new DefaultAzureCredential())
                    .AsChatClient(ModelDeployment))
            .UseOpenTelemetry(sourceName: "MyApp.Eval")
            .Build();
    }

    // ─── Quality evaluators ───────────────────────────────────────────────────
    public static IEvaluator[] QualityEvaluators(IChatClient judge)
    {
        return
        [
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        ];
    }

    // ─── Reporting (compare mode) ─────────────────────────────────────────────
    public static ReportingConfiguration CreateReportingConfig(string runLabel)
    {
        var storageDir = Path.Combine(
            Path.GetDirectoryName(typeof(EvalSetup).Assembly.Location)!,
            "eval-results");

        return new ReportingConfiguration(
            storageRootPath: storageDir,
            executionName: runLabel,
            chatConfiguration: null);
    }
}

