using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry.Trace;
using System.Text.Json;

namespace MyApp.Eval;

[TestClass]
public sealed class QualityTests
{
    private static TracerProvider s_telemetry = null!;
    private static IChatClient s_chatClient = null!;
    private static IChatClient s_judge = null!;

    [ClassInitialize]
    public static void Init(TestContext _)
    {
        s_telemetry = EvalSetup.BuildTelemetry();
        s_chatClient = EvalSetup.CreateChatClient();
        s_judge = EvalSetup.CreateChatClient(); // judge model
    }

    [ClassCleanup]
    public static void Cleanup()
    {
        s_telemetry?.Dispose();
        (s_chatClient as IDisposable)?.Dispose();
        (s_judge as IDisposable)?.Dispose();
    }

    [TestMethod]
    [DynamicData(nameof(LoadScenarios), DynamicDataSourceType.Method)]
    public async Task Quality_MeetsThreshold(string name, string userMessage, string context)
    {
        // Arrange
        var messages = new List<ChatMessage> { new(ChatRole.User, userMessage) };
        var evaluators = EvalSetup.QualityEvaluators(s_judge);

        // Act
        var response = await s_chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        // Evaluate
        var evalResults = new Dictionary<string, EvaluationResult>();
        foreach (var evaluator in evaluators)
        {
            var result = await evaluator.EvaluateAsync(messages, new EvaluatorContext
            {
                GroundTruthContext = context
            });
            foreach (var kvp in result)
                evalResults[kvp.Key] = kvp.Value;
        }

        // Assert all quality scores ≥ 3/5
        foreach (var (metric, result) in evalResults)
        {
            var score = result.NumericScore;
            Assert.IsTrue(
                score >= 3,
                $"[{name}] {metric} scored {score}/5 — below threshold.");
        }
    }

    private static IEnumerable<object[]> LoadScenarios()
    {
        var path = Path.Combine(
            Path.GetDirectoryName(typeof(QualityTests).Assembly.Location)!,
            "Scenarios", "quality.json");

        if (!File.Exists(path))
            yield break;

        var scenarios = JsonSerializer.Deserialize<List<QualityScenario>>(
            File.ReadAllText(path))!;

        foreach (var s in scenarios)
            yield return [s.Name, s.UserMessage, s.Context ?? ""];
    }
}

internal record QualityScenario(string Name, string UserMessage, string? Context);

