using Microsoft.Extensions.AI;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry.Trace;
using System.Diagnostics;

namespace MyApp.Eval;

/// <summary>
/// Telemetry mode: validates that AI interactions produce proper
/// OpenTelemetry spans with expected attributes.
/// </summary>
[TestClass]
public sealed class TelemetryTests
{
    private static readonly ActivitySource Source = new("MyApp.Eval");

    [TestMethod]
    public async Task Telemetry_EmitsSpanForChatCompletion()
    {
        var exportedSpans = new List<Activity>();

        using var tp = OpenTelemetry.Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("MyApp.Eval")
            .AddInMemoryExporter(exportedSpans)
            .Build()!;

        using var client = EvalSetup.CreateChatClient();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Say hello in one word.")
        };

        var response = await client.GetResponseAsync(messages);

        tp.ForceFlush();

        Assert.IsTrue(exportedSpans.Count > 0, "Expected at least one telemetry span.");

        var chatSpan = exportedSpans.FirstOrDefault(a =>
            a.DisplayName.Contains("chat", StringComparison.OrdinalIgnoreCase));

        Assert.IsNotNull(chatSpan, "Expected a 'chat' span from the AI client pipeline.");
    }

    [TestMethod]
    public async Task Telemetry_SpanContainsModelAttribute()
    {
        var exportedSpans = new List<Activity>();

        using var tp = OpenTelemetry.Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("MyApp.Eval")
            .AddInMemoryExporter(exportedSpans)
            .Build()!;

        using var client = EvalSetup.CreateChatClient();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is 2+2?")
        };

        await client.GetResponseAsync(messages);
        tp.ForceFlush();

        var chatSpan = exportedSpans.FirstOrDefault(a =>
            a.DisplayName.Contains("chat", StringComparison.OrdinalIgnoreCase));

        Assert.IsNotNull(chatSpan);

        var modelTag = chatSpan.Tags.FirstOrDefault(t =>
            t.Key.Contains("model", StringComparison.OrdinalIgnoreCase));

        Assert.IsNotNull(modelTag.Value, "Expected model attribute on the chat span.");
    }
}

